import { defineComponent, computed, h } from 'vue';
import { getProgressOffset, progressStyleKeys } from '../lib/core';
import styles from './progress.module.scss';

export const Progress = defineComponent({
	name: 'Progress',
	props: {
		value: { type: Number, default: 0 },
		min: { type: Number, default: 0 },
		max: { type: Number, default: 100 },
	},
	setup(props, { attrs }) {
		const offset = computed(() => getProgressOffset(props.value, props.min, props.max));

		return () =>
			h(
				'div',
				{
					...attrs,
					role: 'progressbar',
					'aria-valuemin': props.min,
					'aria-valuemax': props.max,
					'aria-valuenow': props.value,
					class: [styles[progressStyleKeys.root], attrs.class],
				},
				[h('div', { class: styles[progressStyleKeys.indicator], style: { transform: `translateX(-${100 - offset.value}%)` } })],
			);
	},
});

export default Progress;

@use '../../../styles/variables/colors' as *;

.root {
	position: relative;
	height: 0.5rem;
	width: 100%;
	overflow: hidden;
	border-radius: $radius-full;
	background-color: var(--tile-progress-track, color-mix(in srgb, $primary 20%, transparent));
}

.indicator {
	height: 100%;
	width: 100%;
	flex: 1;
	background-color: var(--tile-progress-indicator, $primary);
	transition: transform $transition-normal;
}
